INSERT INTO fc_chem_style_effects VALUES(1,'FC27',1,'특화 없음 — 16개 속성이 고르게 +3씩 오른다. 케미 스타일을 아직 정하지 못한 선수용 기본값.','질주 속도 +3 → 주행 속도(A · FC27 #12) · 슈팅력 +3 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 시야 +3 → 작용 서술 없음(A 부재 · #55) · 짧은 패스 +3 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 긴 패스 +3 → 스루패스 커브(A · FC26 #54) · 커브 +3 → 스루패스 커브(A · FC26 #54) · 민첩성 +3 → 드리블 동작 속도·전환·오프밸런스(A · FIFA 23/FC27 #92) · 볼컨트롤 +3 → 터치 정확도·공 밀착(A · FIFA 23 #94) + 퍼스트 터치(A · FC26 #23) · 드리블 +3 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 침착 +3 → 퍼스트 터치(A · FC26 #23) + 페널티킥 타이밍 원(A · FC25 #26) · 힘 +3 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 공격 위치 선정 +3 · 페널티킥 +3 · 수비 위치 선정 +3 · 스탠딩 태클 +3 · 슬라이딩 태클 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(2,'FC27',2,'박스 근처 자리 잡기와 몸싸움이 낫다. 중거리슛과 체력도 함께 오른다 — 등지고 버티며 마무리하는 공격수.','힘 +9 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 · 슈팅력 +3 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 공격성 +3 → 쉴딩·몸싸움(A · FC26 #53) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 공격 위치 선정 +9 · 중거리슛 +6 · 체력 +6 · 결정력 +3 · 발리 슛 +3 · 페널티킥 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(3,'FC27',3,'박스 안 마무리와 드리블이 낫다. 결정력에 더해 드리블 터치·동작 속도·부딪혀도 이어 가는 드리블이 모두 오른다.','드리블 +9 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 민첩성 +6 → 드리블 동작 속도·전환·오프밸런스(A · FIFA 23/FC27 #92) · 슈팅력 +3 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 균형 감각 +3 → 드리블 동작 전환·오프밸런스(A · FIFA 23/FC27 #92·#24) · 반응력 +3 → 드리블 동작 속도·전환·드리블 중 속도 유지(A · FIFA 23 #95) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 결정력 +9 · 공격 위치 선정 +6 · 발리 슛 +3 · 페널티킥 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(4,'FC27',4,'강하게 차는 슈팅과 짧은 패스 연결이 낫다. 슈팅 속도와 커브가 오른다 — 연계 후 슈팅하는 공격수.','슈팅력 +9 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 짧은 패스 +9 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 커브 +6 → 스루패스 커브(A · FC26 #54) · 시야 +3 → 작용 서술 없음(A 부재 · #55) · 긴 패스 +3 → 스루패스 커브(A · FC26 #54) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 공격 위치 선정 +6 · 결정력 +3 · 중거리슛 +3 · 페널티킥 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(5,'FC27',5,'받아서 처리하는 마무리가 낫다. 첫 터치·공 밀착(볼컨트롤)과 몸싸움(힘)이 오르고, 결정력·중거리슛이 더해진다.','반응력 +6 → 드리블 동작 속도·전환·드리블 중 속도 유지(A · FIFA 23 #95) · 볼컨트롤 +6 → 터치 정확도·공 밀착(A · FIFA 23 #94) + 퍼스트 터치(A · FC26 #23) · 힘 +6 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 · 슈팅력 +3 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 드리블 +3 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 침착 +3 → 퍼스트 터치(A · FC26 #23) + 페널티킥 타이밍 원(A · FC25 #26) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 결정력 +6 · 중거리슛 +6 · 페널티킥 +3 · 점프 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(6,'FC27',6,'슈팅 파워와 공중볼·몸싸움이 낫다. 속도도 조금 오른다 — 높이와 힘으로 싸우는 공격수.','슈팅력 +6 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 공격성 +6 → 쉴딩·몸싸움(A · FC26 #53) · 가속 +3 → 주행 속도(A · FC27 #12) · 질주 속도 +3 → 주행 속도(A · FC27 #12) · 힘 +3 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 중거리슛 +6 · 점프 +6 · 공격 위치 선정 +3 · 결정력 +3 · 페널티킥 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(7,'FC27',7,'동작이 빠르고 끊김이 짧다. 부딪혀도 드리블을 이어 가는 쪽이 낫다. 크로스·커브도 크게 오른다.','커브 +9 → 스루패스 커브(A · FC26 #54) · 민첩성 +9 → 드리블 동작 속도·전환·오프밸런스(A · FIFA 23/FC27 #92) · 긴 패스 +6 → 스루패스 커브(A · FC26 #54) · 반응력 +6 → 드리블 동작 속도·전환·드리블 중 속도 유지(A · FIFA 23 #95) · 시야 +3 → 작용 서술 없음(A 부재 · #55) · 짧은 패스 +3 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 드리블 +3 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 침착 +3 → 퍼스트 터치(A · FC26 #23) + 페널티킥 타이밍 원(A · FC25 #26) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 크로스 +6','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(8,'FC27',8,'짧은 패스 연결과 볼 지키기가 낫다. 힘이 크게 올라 등지고 버티며 연결하는 플레이에 맞는다.','짧은 패스 +9 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 힘 +9 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 · 시야 +6 → 작용 서술 없음(A 부재 · #55) · 커브 +6 → 스루패스 커브(A · FC26 #54) · 긴 패스 +3 → 스루패스 커브(A · FC26 #54) · 공격성 +3 → 쉴딩·몸싸움(A · FC26 #53) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 체력 +6 · 프리킥 정확도 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(9,'FC27',9,'패스와 태클·차단이 함께 낫다 — 공을 뺏고 바로 연결하는 중앙 미드필더.','시야 +9 → 작용 서술 없음(A 부재 · #55) · 짧은 패스 +6 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 긴 패스 +6 → 스루패스 커브(A · FC26 #54) · 차단력 +6 → 퍼스트 터치 입력(A · FC26 #23) · 커브 +3 → 스루패스 커브(A · FC26 #54) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 스탠딩 태클 +9 · 수비 위치 선정 +3 · 슬라이딩 태클 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(10,'FC27',10,'공을 받고 다루는 쪽이 낫다. 받는 첫 터치가 안정적이고 공이 발에 붙는다. 여기에 슈팅(중거리슛·슈팅력) 상승이 더해진다.','긴 패스 +6 → 스루패스 커브(A · FC26 #54) · 볼컨트롤 +6 → 터치 정확도·공 밀착(A · FIFA 23 #94) + 퍼스트 터치(A · FC26 #23) · 슈팅력 +3 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 시야 +3 → 작용 서술 없음(A 부재 · #55) · 짧은 패스 +3 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 반응력 +3 → 드리블 동작 속도·전환·드리블 중 속도 유지(A · FIFA 23 #95) · 드리블 +3 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 침착 +3 → 퍼스트 터치(A · FC26 #23) + 페널티킥 타이밍 원(A · FC25 #26) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 중거리슛 +6 · 프리킥 정확도 +6 · 공격 위치 선정 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(11,'FC27',11,'드리블 동작 전환과 부딪혀도 이어 가는 드리블이 낫다(균형·드리블). 크로스와 속도도 조금 오른다 — 측면에서 몰고 올라가는 선수.','커브 +6 → 스루패스 커브(A · FC26 #54) · 균형 감각 +6 → 드리블 동작 전환·오프밸런스(A · FIFA 23/FC27 #92·#24) · 드리블 +6 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 가속 +3 → 주행 속도(A · FC27 #12) · 질주 속도 +3 → 주행 속도(A · FC27 #12) · 시야 +3 → 작용 서술 없음(A 부재 · #55) · 짧은 패스 +3 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 긴 패스 +3 → 스루패스 커브(A · FC26 #54) · 민첩성 +3 → 드리블 동작 속도·전환·오프밸런스(A · FIFA 23/FC27 #92) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 크로스 +6','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(12,'FC27',12,'자리 잡는 수비와 공중볼이 낫다. 수비 위치 선정·점프가 크게 오르고 몸싸움(공격성)도 더해진다.','차단력 +6 → 퍼스트 터치 입력(A · FC26 #23) · 공격성 +6 → 쉴딩·몸싸움(A · FC26 #53) · 힘 +3 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 수비 위치 선정 +9 · 점프 +9 · 헤딩 정확도 +6 · 스탠딩 태클 +3 · 슬라이딩 태클 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(13,'FC27',13,'태클과 함께 드리블 동작이 빨라진다 — 공을 뺏고 직접 몰고 나가는 수비수.','민첩성 +6 → 드리블 동작 속도·전환·오프밸런스(A · FIFA 23/FC27 #92) · 드리블 +6 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 반응력 +3 → 드리블 동작 속도·전환·드리블 중 속도 유지(A · FIFA 23 #95) · 볼컨트롤 +3 → 터치 정확도·공 밀착(A · FIFA 23 #94) + 퍼스트 터치(A · FC26 #23) · 침착 +3 → 퍼스트 터치(A · FC26 #23) + 페널티킥 타이밍 원(A · FC25 #26) · 차단력 +3 → 퍼스트 터치 입력(A · FC26 #23) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 스탠딩 태클 +9 · 수비 위치 선정 +6 · 슬라이딩 태클 +6','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(14,'FC27',14,'공수 겸용 — 슈팅 속도와 드리블 중 속도 유지가 오르고 슬라이딩 태클이 더해진다. 고르게 조금씩.','슈팅력 +6 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) · 반응력 +6 → 드리블 동작 속도·전환·드리블 중 속도 유지(A · FIFA 23 #95) · 균형 감각 +3 → 드리블 동작 전환·오프밸런스(A · FIFA 23/FC27 #92·#24) · 볼컨트롤 +3 → 터치 정확도·공 밀착(A · FIFA 23 #94) + 퍼스트 터치(A · FC26 #23) · 드리블 +3 → 터치 정확도·공 밀착·동작 속도·속도 유지·오프밸런스(A · FIFA 23/FC27 #92·#94) · 차단력 +3 → 퍼스트 터치 입력(A · FC26 #23) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 슬라이딩 태클 +6 · 공격 위치 선정 +3 · 중거리슛 +3 · 헤딩 정확도 +3 · 수비 위치 선정 +3 · 스탠딩 태클 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(15,'FC27',15,'수비형 미드필더용 — 차단·태클·긴 패스가 오르고 몸싸움(공격성)과 체력이 더해진다.','긴 패스 +6 → 스루패스 커브(A · FC26 #54) · 차단력 +6 → 퍼스트 터치 입력(A · FC26 #23) · 공격성 +6 → 쉴딩·몸싸움(A · FC26 #53) · 시야 +3 → 작용 서술 없음(A 부재 · #55) · 짧은 패스 +3 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 힘 +3 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 스탠딩 태클 +6 · 체력 +6 · 수비 위치 선정 +3 · 슬라이딩 태클 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(16,'FC27',16,'몸싸움과 공중볼에 강한 수비가 낫다(힘·점프·태클). 속도도 조금 오른다.','힘 +6 → 쉴딩·어깨싸움·공중볼 박스아웃(A · FC26 #53·#56) + AcceleRATE 판정 · 가속 +3 → 주행 속도(A · FC27 #12) · 질주 속도 +3 → 주행 속도(A · FC27 #12) · 차단력 +3 → 퍼스트 터치 입력(A · FC26 #23) · 공격성 +3 → 쉴딩·몸싸움(A · FC26 #53) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 스탠딩 태클 +6 · 슬라이딩 태클 +6 · 점프 +6 · 헤딩 정확도 +3 · 수비 위치 선정 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(17,'FC27',17,'주행 속도가 크게 오르고 발리·페널티킥이 더해진다 — 뒷공간을 달리는 공격수.','가속 +6 → 주행 속도(A · FC27 #12) · 질주 속도 +6 → 주행 속도(A · FC27 #12) · 슈팅력 +3 → 슈팅 속도(A · FC27 「핵심 슈팅 능력치로 비례」) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 발리 슛 +9 · 페널티킥 +6 · 공격 위치 선정 +3 · 결정력 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(18,'FC27',18,'주행 속도가 크게 오르고 크로스·긴 패스가 더해진다 — 달려서 올려 주는 측면 선수.','시야 +9 → 작용 서술 없음(A 부재 · #55) · 가속 +6 → 주행 속도(A · FC27 #12) · 질주 속도 +6 → 주행 속도(A · FC27 #12) · 긴 패스 +6 → 스루패스 커브(A · FC26 #54) · 짧은 패스 +3 → 땅볼 패스 정확도·스루패스 커브(A · FC26 #54) · 커브 +3 → 스루패스 커브(A · FC26 #54) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 크로스 +6','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(19,'FC27',19,'주행 속도가 크게 오르고 슬라이딩 태클·헤딩이 더해진다 — 빠른 수비수.','가속 +6 → 주행 속도(A · FC27 #12) · 질주 속도 +6 → 주행 속도(A · FC27 #12) · 차단력 +3 → 퍼스트 터치 입력(A · FC26 #23) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 슬라이딩 태클 +9 · 헤딩 정확도 +6 · 수비 위치 선정 +3 · 스탠딩 태클 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(20,'FC27',20,'특화 없음 — GK 속성이 고르게 +3씩 오르고 가속도 조금 오른다.','가속 +3 → 주행 속도(A · FC27 #12) · 반사신경 +3 → 시야 가림이 선방에 주는 영향(A · FIFA 23 #95) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 다이빙 +3 · 킥 +3 · 핸들링 +3 · 포지셔닝 +3','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(21,'FC27',21,'다이빙이 크게 오르고 킥이 더해진다 — 멀리 뻗는 선방.',' ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 다이빙 +9 · 킥 +6 · 핸들링 +3','D 수준 — 오르는 속성 모두 EA 작용 서술 없음(이름 그대로)','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(22,'FC27',22,'핸들링이 크게 오른다 — 잡아내는 선방(튕겨 내는 공이 줄어든다는 체감은 D).',' ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 핸들링 +9 · 다이빙 +6 · 포지셔닝 +3','D 수준 — 오르는 속성 모두 EA 작용 서술 없음(이름 그대로)','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(23,'FC27',23,'반사신경이 크게 오른다 — 가까운 거리·시야가 가린 슈팅에 반응하는 선방. 킥도 더해진다.','반사신경 +9 → 시야 가림이 선방에 주는 영향(A · FIFA 23 #95) · 질주 속도 +3 → 주행 속도(A · FC27 #12) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 킥 +6','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
INSERT INTO fc_chem_style_effects VALUES(24,'FC27',24,'포지셔닝이 크게 오르고 반사신경이 더해진다 — 자리를 먼저 잡는 골키퍼.','반사신경 +6 → 시야 가림이 선방에 주는 영향(A · FIFA 23 #95) · 가속 +3 → 주행 속도(A · FC27 #12) ‖ 이름 그대로(EA가 작용 방식을 밝히지 않음): 포지셔닝 +9','A(작용 근거 있는 속성 포함) — 근거 버전은 속성별 표기 · FC27 문서로 재확인된 것은 오프밸런스·주행 속도·슈팅 속도뿐','부스트 = fc_chemistry_styles(fut.gg 번들 · 최대 케미 3점) · 작용 = game_system_changes 근거 행 · 한 줄 정의는 2026-11-05 부모 세션 작성(만잠비 Artist/Maestro 비교 문형은 사용자 확인)','2026-11-05');
